mapper.select:
select d.shop_code, d.orderdetailcode, d.goodscode, sum(d.qty) as qty
  from sdsorder.u_f_shipbatchdetail_${tableSuffix} d
  join sdsorder.u_f_shipbatch_${tableSuffix} b
    on b.shop_code = d.shop_code and b.shipcode = d.shipcode
 where d.shop_code = #{shopCode}
   and b.ordercode = #{orderCode}
   and b.status in
   #{s}
 and b.shipcode != #{excludeShipCode}
 group by d.shop_code, d.orderdetailcode, d.goodscode

mapper.update:
update sdsorder.u_f_shipbatchdetail_${tableSuffix}
   set qty = #{qty}
 where shop_code = #{shopCode} and detailcode = #{detailCode}

mapper.select:
select coalesce(sum(qty), 0)
  from sdsorder.u_f_shipbatchdetail_${tableSuffix}
 where shop_code = #{shopCode} and shipcode = #{shipCode}
